    /**
     * @group performance
     */
    public function test_callCreate_performance_302(): void
    {
        $this->loginMockUser();
        $ctrl = new DealController();
        
        $memBefore = memory_get_usage(true);
        $timeBefore = microtime(true);
        
        try {
            for ($i = 0; $i < 3; $i++) {
                $ctrl->callCreate($this->makeRequest(), 1);
            }
        } catch (\Throwable $e) {
            // Method may throw, that's OK for perf test
        }
        
        $timeAfter = microtime(true);
        $memAfter = memory_get_usage(true);
        
        $execTime = ($timeAfter - $timeBefore) * 1000; // ms
        $memUsed = ($memAfter - $memBefore) / 1024 / 1024; // MB
        
        // Assert reasonable performance bounds
        $this->assertLessThan(5000, $execTime, "callCreate took > 5s for 3 iterations");
        $this->assertLessThan(50, $memUsed, "callCreate used > 50MB for 3 iterations");
    }

